const observer = new IntersectionObserver((entries, observerInstance) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      console.log('Element has entered the viewport!');
      const img = entry.target;
      img.src = img.dataset.src; // Lazy load the image

      // Stop watching it once it's loaded to save memory
      observerInstance.unobserve(img);
    }
  });
}, { threshold: 0.1 }); // Fire when 10% visible

// Start watching an element
const target = document.querySelector('.lazy-image');
observer.observe(target);
